// Expected values taken from Cursor's own code, never from this package. The fixture is regenerated by
// parity/pstack-source-audit-2026-11-05/probe-agents.mjs, which runs Cursor's plugin-agent loader and agent definitions.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

import { PACKAGE_ROOT } from '../src/paths.ts';

export interface CursorAgent {
  type: string;
  description: string;
  model: string;
  readonly: boolean;
  background: boolean;
  tools: string[];
  reminder: string;
}

export const cursorAgents = JSON.parse(readFileSync(join(PACKAGE_ROOT, 'test/fixtures/cursor-agent-definitions.json'), 'utf8')) as {
  subagentReminder: string;
  builtIns: Pick<CursorAgent, 'type' | 'description' | 'reminder'>[];
  agents: CursorAgent[];
  task: { description: string; parameters: Record<string, string> };
};

// The only wording Pi changes in Cursor's Task text: Pi's tool names, and the catalogs in the pstack_subagents
// section instead of Cursor's user-info message.
const TASK_WORDING: readonly (readonly [string, string])[] = [
  ['[Uses Grep directly', '[Uses grep directly'],
  ['use the Read or Glob tool instead', 'use the read or find tool instead'],
  ['use the Read tool instead', 'use the read tool instead'],
  ['use the Glob tool instead', 'use the find tool instead'],
  ['are listed in <available_subagent_types> in the initial user-info message at the start of this conversation.', 'are listed in <pstack_subagents> in the system prompt.'],
  ['are listed in <available_subagent_models> in the initial user-info message at the start of this conversation.', 'are listed in <pstack_subagents> in the system prompt.'],
  ['are listed in <available_subagent_models> in the initial user-info message.', 'are listed in <pstack_subagents> in the system prompt.'],
  ['Available types are listed in the initial user-info message.', 'Available types are listed in <pstack_subagents> in the system prompt.'],
];

export const cursorToolText = JSON.parse(readFileSync(join(PACKAGE_ROOT, 'test/fixtures/cursor-tool-text.json'), 'utf8')) as {
  tools: Record<string, { description: string; parameters: Record<string, string>; required: string[] }>;
};

// What Pi leaves out of Cursor's tool descriptions: modes, renderers, and a user action Pi does not have.
const TOOL_OMISSIONS: Record<string, readonly string[]> = {
  SwitchMode: [
    '### Debug Mode (cannot switch to this mode)\nSystematic troubleshooting mode for investigating bugs, failures, and unexpected behavior with runtime evidence.\n\n### Ask Mode (cannot switch to this mode)\nRead-only mode for exploring code and answering questions without making changes.\n\n',
  ],
  AwaitShell: [', because it renders nicely to the user', '\n- Never poll a task whose tool result says it was "manually backgrounded by the user".'],
};

/** Cursor's description of a tool, minus what Pi lacks. Each omission must apply, so a Cursor text that moves fails here. */
export function cursorToolDescription(name: string): string {
  let text = cursorToolText.tools[name]?.description ?? '';
  for (const omission of TOOL_OMISSIONS[name] ?? []) {
    if (!text.includes(omission)) throw new Error(`${name}: omission not found: ${omission.slice(0, 40)}`);
    text = text.replace(omission, '');
  }
  return text;
}

/** Cursor's Task text in Pi's wording. Each change must apply, so a Cursor text that moves fails here. */
export function cursorTaskText(text: string, expectedChanges: number): string {
  let changed = 0;
  let result = text;
  for (const [from, to] of TASK_WORDING)
    if (result.includes(from)) {
      result = result.replaceAll(from, to);
      changed += 1;
    }
  if (changed !== expectedChanges) throw new Error(`expected ${expectedChanges} wording changes, applied ${changed}`);
  return result;
}

/** The only wording Pi changes in Cursor's subagent reminders: Pi has no Cursor Canvas, and the product is Pi. */
export const forPi = (text: string): string =>
  text
    .replace(' Do not create Cursor Canvas files unless requested by the user or by your instructions.', '')
    .replace('You are a file search specialist for Cursor, an application to write code with AI.', 'You are a file search specialist for Pi, an application to write code with AI.');

/** The full system reminder Cursor gives a subagent of this type, in Pi's wording. */
export function cursorReminder(type: string): string {
  const agent = [...cursorAgents.builtIns, ...cursorAgents.agents].find((candidate) => candidate.type === type);
  if (agent === undefined) throw new Error(`No Cursor reference for subagent type ${type}`);
  return forPi(agent.reminder);
}
